27	/**
28	 * J/K moves keep showing the previous conversation (never actionable) for this
29	 * long before the loading presentation replaces it, so a fast response never
30	 * produces an intermediate empty frame.
31	 */
32	export const READER_LOADING_DELAY_MS = 120;
33	/** Neighbor-detail cache bounds (read-only prefetch; see `prefetchConversation`). */
34	export const DETAIL_CACHE_MAX = 3;
35	export const DETAIL_CACHE_TTL_MS = 30_000;
36	
37	export type ListState = 'loading' | 'ready' | 'error';
38	export type DetailState = 'idle' | 'loading' | 'ready' | 'error';
39	export type AccountState = 'loading' | 'ready' | 'error';
40	export type AccountAction = 'connect' | 'disconnect' | 'sync' | 'enable-actions' | 'cancel-upgrade';
41	export type ConversationSummaryLike = InboxSnapshot['conversations'][number];
42	export type OperationSummaryLike = InboxSnapshot['activity'][number];
43	/** The setter action an undoable last action was performed with. */
44	export type LastActionId = 'archive' | 'unarchive' | 'read' | 'unread' | 'star' | 'unstar';
