46	/**
47	 * Single-slot notice state for the most recent accepted conversation action
48	 * (UX-04). `undoableUntil` comes from the refreshed activity row, never from a
49	 * local guess; the backend stays the authority on undo eligibility.
50	 */
51	export interface LastAction {
52	  /** The accepted operation. `acceptedAt` is carried only when it is real:
53	   * a re-pointed slot knows no acceptance time and fabricates none. */
54	  receipt: { operationId: string; acceptedAt?: string };
55	  actionId: LastActionId;
56	  target: ConversationRef;
57	  /** Best-effort subject; null when no row carried one — never a raw id. */
58	  subject: string | null;
59	  undoableUntil: string | null;
60	  /** True once this action ever had an undo window; the expired wording is
61	   * shown only then, never for actions that were never undoable. */
62	  hadWindow: boolean;
63	  /** Receipt of a successful undo of this action. Keeps the slot alive after
64	   * the undo so the notice can report Cancelled/Restored/compensation outcome. */
65	  undone: UndoReceipt | null;
66	}
