68	export function sameConversation(a: ConversationRef | null, b: ConversationRef | null): boolean {
69	  return a !== null && b !== null && a.accountId === b.accountId && a.conversationId === b.conversationId;
70	}
71	
72	/**
73	 * `reminders` and `drafts` are list contexts whose rows are not conversations:
74	 * the mailbox only tracks that one is the active context (history, Back, reader
75	 * origin); `useReminders` and `useDrafts` own their rows.
76	 */
77	export type BrowseContext = 'inbox' | 'saved' | 'done' | 'starred' | 'trash' | 'reminders' | 'drafts' | 'search';
78	
79	/**
80	 * UX-05 product/safety bound for selection and groups (docs/ux-05-safe-bulk-
81	 * processing.md §3.1). The UI rejects additions beyond this bound; the stores
82	 * re-validate and never truncate.
83	 */
84	export const SELECTION_MAX = OPERATION_GROUP_MAX_MEMBERS;
85	
86	/**
87	 * Single-slot group notice (UX-05 §3.2/§4.3): the explicit pending identity of
88	 * one bulk action. It carries the ORIGINAL request id and the exact original
89	 * command until acceptance is resolved — a rejected IPC promise alone never
90	 * establishes that nothing committed, and recovery replays that exact request,
91	 * never a fresh one. The persisted member list (not the live selection) drives
92	 * progress/recovery after dispatch.
93	 */
94	export interface GroupNotice {
95	  requestId: string;
96	  accountId: string;
97	  kind: 'archive' | 'read' | 'star';
98	  requestedArchived?: boolean;
99	  requestedRead?: boolean;
100	  requestedStarred?: boolean;
101	  /** Frozen dispatch-order member refs (current loaded order at dispatch). */
102	  members: ConversationRef[];
103	  /**
104	   * `awaiting-acceptance`: the IPC round trip is still open.
105	   * `acceptance-unknown`: the promise rejected but nothing established that
106	   * nothing committed; recovery queries/replays the original request.
107	   * `accepted`: a durable receipt is known.
108	   */
109	  state: 'awaiting-acceptance' | 'acceptance-unknown' | 'accepted';
110	  receipt: OperationGroupReceipt | null;
111	  /** Authoritative member statuses/undo availability from `getOperationGroup`. */
112	  status: OperationGroupStatus | null;
113	  /** True when the latest authoritative status read FAILED (distinct from
114	   * absence — never rendered as "Accepting…"). */
115	  statusError: boolean;
116	  /** Receipt of the group's single Undo attempt, once accepted. */
117	  undone: GroupUndoReceipt | null;
118	  /** True once this group ever had an undo window. */
119	  hadWindow: boolean;
120	  /** The exact original command, replayed verbatim for lost-response recovery. */
121	  originalCommand: SetArchivedGroup | SetReadGroup | SetStarredGroup;
122	}
