124	export interface SearchVisit { query: string; cachedOnly: boolean; coverage: string; rows: ConversationSummaryLike[]; cursor: string | null }
125	
126	export interface DoneBoundary { lastMessageAt: string; conversationId: string }
127	function reachesBoundary(rows: ConversationSummaryLike[], boundary: DoneBoundary | null): boolean {
128	  const last = rows.at(-1);
129	  return !boundary || !!last && (last.lastMessageAt < boundary.lastMessageAt
130	    || last.lastMessageAt === boundary.lastMessageAt && last.ref.conversationId >= boundary.conversationId);
131	}
132	function boundaryOf(rows: ConversationSummaryLike[]): DoneBoundary | null {
133	  const last = rows.at(-1);
134	  return last ? { lastMessageAt: last.lastMessageAt, conversationId: last.ref.conversationId } : null;
135	}
