138	  savedSplit: Ref<SavedSplit | null>;
139	  splitError: Ref<MailError | null>;
140	  splitBusy: Ref<boolean>;
141	  inboxTotal: Ref<number | null>;
142	  savedTotal: Ref<number | null>;
143	  unreadOnly: Ref<boolean>;
