148	  searchCachedOnly: Ref<boolean>;
149	  search(query: string, cachedOnly?: boolean): Promise<void>;
150	  restoreSearch(visit: SearchVisit): Promise<void>;
151	  /** Explicit navigation supersedes a search still awaiting cancellation. */
152	  invalidateSearchIntent(): void;
153	  /** Capture current ownership for deferred navigation, without claiming a new intent. */
154	  captureNavigationIntent(): () => boolean;
155	  context: Ref<BrowseContext>;
156	  starredOnly: Ref<boolean>;
157	  nextCursor: Ref<string | null>;
158	  loadingMore: Ref<boolean>;
159	  exactTotal: Ref<number | null>;
160	  lastSyncedAt: Ref<string | null>;
161	  activityError: Ref<MailError | null>;
162	  loadedDonePages: Ref<number>;
163	  loadedDoneBoundary: Ref<DoneBoundary | null>;
164	  setContext(context: BrowseContext, pages?: number, boundary?: DoneBoundary | null, starredOnly?: boolean): Promise<void>;
165	  loadMore(): Promise<void>;
166	  conversations: Ref<ConversationSummaryLike[]>;
167	  activity: Ref<OperationSummaryLike[]>;
168	  listState: Ref<ListState>;
169	  listError: Ref<MailError | null>;
170	  /** Explicit account-scoped conversation focus; never an array position. */
171	  focusedRef: Ref<ConversationRef | null>;
172	  /** The focused row in the current snapshot; `null` when the ref is absent. */
173	  focusedSummary: ComputedRef<ConversationSummaryLike | null>;
174	  openRef: Ref<ConversationRef | null>;
175	  conversation: Ref<Conversation | null>;
176	  detailState: Ref<DetailState>;
177	  /**
178	   * Display-only previous conversation kept on screen for up to
179	   * READER_LOADING_DELAY_MS while a J/K target loads. It is never an action
180	   * target: `conversation` stays null and `detailState` stays 'loading'.
181	   */
182	  heldConversation: Ref<Conversation | null>;
183	  detailError: Ref<MailError | null>;
184	  lastCommandError: Ref<MailError | null>;
185	  inFlightCommandRef: Ref<ConversationRef | null>;
186	  /** Includes targetless retries; mutation ownership is not a conversation. */
187	  commandInFlight: Ref<boolean>;
188	  /** Authoritative account/mode status; `null` until the first status read lands. */
189	  accountStatus: Ref<AccountStatus | null>;
190	  accountState: Ref<AccountState>;
191	  accountError: Ref<MailError | null>;
192	  accountBusy: Ref<AccountAction | null>;
193	  /** Mode from the last accepted status; `null` while unknown (UI must fail closed). */
194	  mode: ComputedRef<MailMode | null>;
195	  isGmail: ComputedRef<boolean>;
196	  ready: Promise<void>;
197	  refresh(): Promise<void>;
198	  connectAccount(): Promise<void>;
199	  disconnectAccount(): Promise<void>;
200	  requestSync(): Promise<void>;
201	  focusConversation(target: ConversationRef | null): void;
202	  moveFocus(delta: number): void;
203	  openConversationByRef(ref: ConversationRef, source?: 'list' | 'activity'): Promise<void>;
204	  /** J/K and chevron moves: instant from the neighbor cache, else delayed loading. */
205	  openNeighbor(ref: ConversationRef): Promise<void>;
206	  /** Best-effort, read-only prefetch of one neighbor of the ready open reader. */
207	  prefetchConversation(ref: ConversationRef): void;
208	  openFocused(): Promise<void>;
209	  closeReader(): void;
210	  setArchived(target: ConversationRef, archived: boolean): Promise<OperationReceipt | null>;
211	  setStarred(target: ConversationRef, starred: boolean): Promise<OperationReceipt | null>;
212	  setStarredGroup(members: ConversationRef[], starred: boolean): Promise<boolean>;
213	  unarchiveFromActivity(target: ConversationRef): Promise<OperationReceipt | null>;
214	  setRead(target: ConversationRef, read: boolean): Promise<OperationReceipt | null>;
215	  retryOperation(operationId: string): Promise<OperationReceipt | null>;
216	  /** Single-slot notice state for the latest accepted setter action. */
217	  lastAction: Ref<LastAction | null>;
218	  /** Undo of the last action; re-points on `superseded`, exposes `expired`. */
219	  undoLastAction(): Promise<UndoReceipt | null>;
220	  // --- UX-05 selection state (account-scoped, additive ranges) ---
221	  /** Insertion-ordered selected references; never indexes, never focus. */
222	  selectedRefs: Ref<ConversationRef[]>;
223	  /** Range anchor for Shift+J/K and Shift-click ranges. */
224	  rangeAnchorRef: Ref<ConversationRef | null>;
225	  /** Last bound/scope explanation (limit reached, select-all refused). */
226	  selectionNotice: Ref<string | null>;
227	  isSelected(target: ConversationRef): boolean;
228	  /** X / checkbox / Cmd-click: toggle one row and set the anchor there. */
229	  toggleSelected(target: ConversationRef): void;
230	  /** Shift+J/K / Shift-click: additive inclusive anchor→target range. */
231	  extendSelectionTo(target: ConversationRef, fallbackAnchor: ConversationRef | null): void;
232	  /** Select all currently loaded rows; refuses beyond the bound with wording. */
233	  selectAllLoaded(): void;
234	  clearSelection(): void;
235	  /** Exact selected references frozen in current loaded order (dispatch input). */
236	  selectionInLoadedOrder(): ConversationRef[];
237	  // --- UX-05 group actions and single-or-group pending model ---
238	  /** Single-slot group notice; a newer single/group action replaces it. */
239	  lastGroup: Ref<GroupNotice | null>;
240	  /** True only while a group IPC round trip or its recovery replay is open. */
241	  groupInFlight: Ref<boolean>;
242	  /** True while a group acceptance or its receipt recovery is unresolved. */
243	  bulkUnresolved: ComputedRef<boolean>;
244	  setArchivedGroup(members: ConversationRef[], archived: boolean): Promise<boolean>;
245	  setReadGroup(members: ConversationRef[], read: boolean): Promise<boolean>;
246	  /** Lost-response recovery: query/replay the ORIGINAL request id. */
247	  recoverGroupAcceptance(): Promise<void>;
248	  dismissGroupNotice(): void;
249	  /** Partial group Undo (one attempt); rejects surface through the slot. */
250	  undoGroupAction(): Promise<GroupUndoReceipt | null>;
251	  /** Activity: bounded recent group summaries, independent of list rows. */
252	  recentGroups: Ref<OperationGroupSummary[]>;
253	  /** True when the most recent group-history read failed (not an empty result). */
254	  groupsError: Ref<MailError | null>;
255	  /** True when the backend returned a continuation cursor for more groups. */
256	  groupsHasMore: Ref<boolean>;
257	  /** Shared history-read ownership: refresh and continuation cannot overlap. */
258	  groupsLoadingMore: Ref<boolean>;
259	  /** Bounded Activity continuation: appends the next recent-groups page. */
260	  loadMoreGroups(): Promise<void>;
261	  /** Retry a failed recent-groups history read. */
262	  refreshGroups(): Promise<void>;
263	  /** Activity: detail for one group by request id; null while loading/absent. */
264	  groupDetail: Ref<OperationGroupStatus | null>;
265	  /** True when the most recent group-detail read failed (not absence). */
266	  groupDetailError: Ref<MailError | null>;
267	  openGroupDetail(requestId: string): Promise<void>;
268	  /** Undo an arbitrary addressable group from Activity detail. */
269	  undoGroupById(groupId: string): Promise<GroupUndoReceipt | null>;
270	  enableMailboxActions(): Promise<void>;
271	  cancelMailboxActionUpgrade(): Promise<void>;
272	  archiveFocused(): Promise<void>;
