275	export function useMailbox(client: MailClient): Mailbox {
276	  const context = ref<BrowseContext>('inbox');
277	  const starredOnly = ref(false);
278	  const savedSplit = ref<SavedSplit | null>(null);
279	  const splitError = ref<MailError | null>(null);
280	  const splitBusy = ref(false);
281	  const inboxTotal = ref<number | null>(null);
282	  const savedTotal = ref<number | null>(null);
283	  const unreadOnly = ref(false);
284	  const searchQuery = ref('');
285	  const searchCoverage = ref('');
286	  const searchCachedOnly = ref(false);
287	  const loadingMore = ref(false);
288	  const loadedDonePages = ref(1);
289	  const loadedDoneBoundary = ref<DoneBoundary | null>(null);
290	  const nextCursor = ref<string | null>(null);
291	  const exactTotal = ref<number | null>(null);
292	  const lastSyncedAt = ref<string | null>(null);
293	  const activityError = ref<MailError | null>(null);
294	  const conversations = ref<ConversationSummaryLike[]>([]);
295	  const activity = ref<OperationSummaryLike[]>([]);
296	  const listState = ref<ListState>('loading');
297	  const listError = ref<MailError | null>(null);
298	  const focusedRef = ref<ConversationRef | null>(null);
299	  const openRef = ref<ConversationRef | null>(null);
300	  const conversation = ref<Conversation | null>(null);
301	  const detailState = ref<DetailState>('idle');
302	  const heldConversation = ref<Conversation | null>(null);
303	  const detailError = ref<MailError | null>(null);
304	  const lastCommandError = ref<MailError | null>(null);
305	  const inFlightCommandRef = ref<ConversationRef | null>(null);
306	  const commandInFlight = ref(false);
307	  const accountStatus = ref<AccountStatus | null>(null);
308	  const accountState = ref<AccountState>('loading');
309	  const accountError = ref<MailError | null>(null);
310	  const accountBusy = ref<AccountAction | null>(null);
311	  const lastAction = ref<LastAction | null>(null);
312	  const lastGroup = ref<GroupNotice | null>(null);
313	  const groupInFlight = ref(false);
314	  const selectedRefs = ref<ConversationRef[]>([]);
315	  const rangeAnchorRef = ref<ConversationRef | null>(null);
316	  const selectionNotice = ref<string | null>(null);
317	  const recentGroups = ref<OperationGroupSummary[]>([]);
318	  const groupsError = ref<MailError | null>(null);
319	  const groupsHasMore = ref(false);
320	  const groupsLoadingMore = ref(false);
321	  const groupDetail = ref<OperationGroupStatus | null>(null);
322	  const groupDetailError = ref<MailError | null>(null);
323	
324	  let readerSource: 'list' | 'activity' = 'list';
325	  let listToken = 0;
326	  // Explicit query/navigation ownership must survive routine list refreshes.
327	  let navigationIntentToken = 0;
328	  let activityToken = 0;
329	  let detailToken = 0;
330	  // Neighbor-detail cache and single-slot prefetch. `detailEpoch` is bumped by
331	  // every invalidation so older in-flight reads can never publish.
332	  interface CachedDetail { conversation: Conversation; fetchedAt: number }
333	  const detailCache = new Map<string, CachedDetail>();
334	  let detailEpoch = 0;
335	  let prefetchInFlight: { key: string; epoch: number; promise: Promise<Conversation> } | null = null;
336	  let prefetchWanted: ConversationRef | null = null;
337	  let holdTimer: ReturnType<typeof setTimeout> | null = null;
338	  let commandToken = 0;
339	  let mailboxSessionToken = 0;
340	  let statusToken = 0;
341	  let groupDetailToken = 0;
342	  let groupsToken = 0;
343	  let groupStatusFetchToken = 0;
344	  let groupsLoadedPages = 0;
345	  let groupsCursor: string | null = null;
346	  let groupsRefreshPending = false;
347	  let noticeRehydrated = false;
348	  let detached = false;
349	  let unsubscribe: (() => void) | null = null;
350	  let subscriptionAttempt: Promise<void> | null = null;
351	
352	  async function ensureSubscribed(): Promise<void> {
353	    if (unsubscribe || detached) return;
354	    if (!subscriptionAttempt) {
355	      // Share an in-flight attempt; a failed attempt is retried on Retry/focus/online.
356	      subscriptionAttempt = Promise.resolve()
357	        .then(() => client.subscribe(() => { void refresh(); }))
358	        .then((unsub) => {
359	          if (detached) unsub();
360	          else unsubscribe = unsub;
361	        })
362	        .finally(() => { subscriptionAttempt = null; });
363	    }
364	    await subscriptionAttempt;
365	  }
366	
367	  function sameSplit(a: SavedSplit | null, b: SavedSplit | null): boolean {
368	    return a === b || (a !== null && b !== null && a.name === b.name
369	      && a.criterion === b.criterion && a.value === b.value
370	      && a.enabled === b.enabled && a.hideWhenEmpty === b.hideWhenEmpty);
371	  }
372	
373	  /** A new rule cannot inherit the old view's rows, selection or reader visit. */
374	  function invalidateSavedView(): void {
375	    if (context.value !== 'saved') return;
376	    // Activity owns an explicit recovery visit, independent of split membership.
377	    if (readerSource !== 'activity') closeReader(); // fences old list-detail reads
378	    clearSelection();
379	    focusedRef.value = null;
380	    conversations.value = [];
381	    listState.value = 'loading';
382	    listError.value = null;
383	    inboxTotal.value = null;
384	    savedTotal.value = null;
385	  }
386	
387	  /** Independent cache filters compose by intersection; unknown facts never qualify.
388	   *  Cached Trash is a read-only recovery view: it always lists everything, so the unread filter never applies there. */
389	  function matchesCachedFilters(row: ConversationSummaryLike): boolean {
390	    return (!unreadOnly.value || context.value === 'trash' || row.isRead === false)
391	      && (!starredOnly.value || (row.stars?.starredMessages ?? 0) > 0);
392	  }
393	
394	  /** Cached Done, Starred and Trash share one paged, replayable list read. */
395	  function isCachedList(source: BrowseContext): source is 'done' | 'starred' | 'trash' {
396	    return source === 'done' || source === 'starred' || source === 'trash';
397	  }
398	
399	  function readCachedPage(source: 'done' | 'starred' | 'trash', accountId: string, cursor: string | null): Promise<CachedDoneSnapshot | CachedTrashSnapshot> {
400	    const request = { accountId, limit: 100, cursor };
401	    return source === 'starred' ? client.listCachedStarred(request)
402	      : source === 'trash' ? client.listCachedTrash(request)
403	      : client.listCachedDone(request);
404	  }
405	
406	  async function refreshList(token: number): Promise<void> {
407	    const source = context.value;
408	    const account = accountStatus.value?.account?.accountId;
409	    // Activity always comes from the unfiltered inbox snapshot, not Done rows.
410	    const activityRequest = ++activityToken;
411	    const inbox = client.listConversations();
412	    const activityRead = inbox.then((snap) => {
413	      if (detached || activityRequest !== activityToken) return;
414	      activity.value = snap.activity;
415	      activityError.value = null;
416	    }, (raw) => {
417	      if (!detached && activityRequest === activityToken) {
418	        activityError.value = toMailError(raw);
419	      }
420	    });
421	    const current = (): boolean => !detached && token === listToken && source === context.value;
422	    // Stage the definition with the exact Inbox snapshot used for membership and
423	    // totals. Activity never publishes projection state, even if it finishes first.
424	    const projectionRead = (async () => {
425	      let definition = savedSplit.value;
426	      let definitionError: MailError | null = null;
427	      if (account) {
428	        try {
429	          definition = await client.getSavedSplit(account);
430	          if (!current()) return null;
431	          if (!sameSplit(definition, savedSplit.value)) invalidateSavedView();
432	        } catch (raw) {
433	          if (!current()) return null;
434	          definitionError = toMailError(raw);
435	          if (source === 'saved') {
436	            invalidateSavedView();
437	            splitError.value = definitionError;
438	            throw raw;
439	          }
440	        }
441	      }
442	      const snap = await inbox;
443	      if (!current()) return null;
444	      const matching = definition ? snap.conversations.filter((row) => matchesSplit(row, definition!)) : [];
445	      return { definition, definitionError, snap, matching };
446	    })();
447	    // Only Inbox, Saved and the cached lists consume the projection. Drafts,
448	    // Reminders and Search never await it, so a failed Inbox read must not
449	    // surface as an unhandled rejection there. Awaiting callers still see it.
450	    projectionRead.catch(() => {});
451	    const publishProjection = (projection: NonNullable<Awaited<typeof projectionRead>>): void => {
452	      savedSplit.value = projection.definition;
453	      splitError.value = projection.definitionError;
454	      inboxTotal.value = projection.snap.conversations.length;
455	      savedTotal.value = projection.definitionError ? null : projection.matching.length;
456	    };
457	    // Done owns its own list read. A delayed/failed Inbox or definition read must
458	    // not hold Done rows hostage; its badges still use a fenced projection pair.
459	    const doneProjection = isCachedList(source) ? projectionRead.then((projection) => {
460	      if (current() && projection) publishProjection(projection);
461	    }, () => {
462	      if (current()) { inboxTotal.value = null; savedTotal.value = null; }
463	    }) : null;
464	    try {
465	      if (source === 'reminders' || source === 'drafts') {
466	        // These lists read their own transports; the mailbox list is empty.
467	        if (!current()) return;
468	        conversations.value = [];
469	        focusedRef.value = null;
470	        listError.value = null;
471	        listState.value = 'ready';
472	        return;
473	      }
474	      if (source === 'search') {
475	        // Background invalidations refresh loaded identities from cached facts, not
476	        // a new provider traversal that would discard the user's loaded pages.
477	        if (listState.value === 'loading' || listState.value === 'error') {
478	          const page = await client.searchMail({ accountId: account!, query: searchQuery.value, cursor: null, cachedOnly: searchCachedOnly.value });
479	          if (detached || token !== listToken || context.value !== 'search') return;
480	          conversations.value = page.conversations;
481	          nextCursor.value = page.nextCursor;
482	          searchCoverage.value = page.coverage;
483	          // Pin the continuation mode chosen by the backend (e.g. offline),
484	          // so reconnection cannot reinterpret a cached cursor as provider data.
485	          if (page.coverage === 'cached_incomplete') searchCachedOnly.value = true;
486	        } else if (conversations.value.length) {
487	          // Update authoritative action/read overlays without re-running a
488	          // provider traversal or replacing the loaded query/page identities.
489	          const refreshed = new Map<string, ConversationSummaryLike>();
490	          let cursor: string | null = null;
491	          for (let pageNumber = 0; pageNumber < 5; pageNumber += 1) {
492	            const page = await client.searchMail({ accountId: account!, query: searchQuery.value, cursor, cachedOnly: true });
493	            if (detached || token !== listToken || context.value !== 'search') return;
494	            for (const row of page.conversations) refreshed.set(row.ref.conversationId, row);
495	            cursor = page.nextCursor;
496	            if (!cursor || conversations.value.every((row) => refreshed.has(row.ref.conversationId))) break;
497	          }
498	          conversations.value = conversations.value.map((row) => refreshed.get(row.ref.conversationId) ?? row);
499	        }
